const SOURCE_LINKS=[
 ['TransUnion RD · Factores del score','https://www.transunion.do/blog/factores-score-crediticio','Fuente RD · factores y desfases de actualización'],
 ['TransUnion RD · Tus herramientas','https://www.transunion.do/personal/tus-herramientas','Escala 459–848, contenido y exclusiones del historial'],
 ['Equifax República Dominicana','https://www.equifax.com.do/','Referencia institucional (DataCrédito / Equifax), sin fórmula pública certificada'],
 ['ProUsuario · Guía de historial crediticio','https://prousuario.gob.do/media/h24lybkg/claves-para-construir-un-buen-historial-crediticio.pdf','Cinco categorías educativas: 35/30/15/10/10'],
 ['SB · Sociedades de Información Crediticia','https://sb.gob.do/publicaciones/blog-institucional/sociedades-de-informacion-crediticia-de-repositorios-de-datos-a-infraestructura-clave-del-sistema-financiero/','Gobernanza, datos, supervisión e integridad'],
 ['SB · Reglamento de Evaluación de Activos','https://sb.gob.do/media/xnanx3o3/reglamento_de_evaluacion_de_activos_rea_28_09_2017.pdf','Capacidad de pago sujeta a políticas de cada entidad'],
 ['FICO · Factores de un score','https://www.myfico.com/credit-education/whats-in-your-credit-score','Contraste internacional: ingresos fuera de FICO clásico'],
 ['CFPB · Diferencias entre scores','https://www.consumerfinance.gov/data-research/research-reports/the-impact-of-differences-between-consumer- and-creditor-purchased-credit-scores/'.replace('consumer- and','consumer-and'),'Diferencias entre puntaje educativo y modelo bancario']
];
const $=(sel,root=document)=>root.querySelector(sel),$$=(sel,root=document)=>Array.from(root.querySelectorAll(sel));
const clone=o=>JSON.parse(JSON.stringify(o)),clamp=(n,a,b)=>Math.min(b,Math.max(a,n)),N=x=>Number.isFinite(Number(x))?Number(x):0;
const round=x=>Math.round(x), fmt=x=>new Intl.NumberFormat('es-DO',{maximumFractionDigits:1}).format(x), cash=(x,c='DOP')=>new Intl.NumberFormat('es-DO',{style:'currency',currency:c,maximumFractionDigits:0}).format(x),pct=(x,d=1)=>Number.isFinite(x)?(x*100).toFixed(d).replace(/\.0$/,'')+'%':'—';
const sign=x=>x>0?'+'+fmt(x):fmt(x), cls=x=>x>0?'pos':x<0?'neg':'zero';
const safe=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const monthLabel=p=>{const [y,m]=p.split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString('es-DO',{month:'long',year:'numeric'})},tinyMonth=p=>{const [y,m]=p.split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString('es-DO',{month:'short'})};
const monthShift=(p,n)=>{const [y,m]=p.split('-').map(Number),d=new Date(y,m-1+n,1);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`};
function lerp(x,pts){if(x<=pts[0][0])return pts[0][1];for(let i=1;i<pts.length;i++){if(x<=pts[i][0]){let a=pts[i-1],b=pts[i];return a[1]+(x-a[0])/(b[0]-a[0])*(b[1]-a[1])}}return pts.at(-1)[1]}
const CAP_DEFAULT={dti:.35,floor:5000,reserve:.10,informal:{verified:.85,declared:.60,self:.30,none:0}};
let DB={version:3,engine:ENGINE,metadata:{},settings:clone(CAP_DEFAULT),months:[],seals:[]},idx=0,tab='summary',dark=false,editIndex=0,drawerFocus=null,sim={cardId:'',payment:15000,loanPrincipal:0,loanAnnualRate:20,loanMonths:36,newCreditLimit:0,limitRequested:false,late30:false,formalDelta:0,informalDelta:0,fxShock:0,expenseDelta:0},filters={matrix:'',scope:'all'},auditHistory=[];
function current(){return DB.months[idx]}function selectMonth(i){idx=clamp(+i,0,DB.months.length-1);render()}
function conversion(n,cur,s){return N(n)*(cur==='USD'?N(s.txRate):1)}
function eqCards(s){return s.cards.filter(c=>c.status!=='closed').map(c=>({...c,limitD:conversion(c.limit,c.currency,s),balanceD:conversion(c.balance,c.currency,s),advanceD:conversion(c.advance,c.currency,s),minD:conversion(c.min,c.currency,s),stmtD:conversion(c.statementBalance,c.currency,s)}))}
function part(id,label,points,max,metric,rule,extra=''){return {id,label,points:round(clamp(points,0,max)),max,metric,rule,extra}}
function evaluate(s){
 const cards=eqCards(s),all=s.cards.concat(s.loans),activeCredit=all.filter(x=>x.status!=='closed'),errors=validate(s),major=errors.filter(e=>e.level==='critical');
 let parts={};
 const dpd=Math.max(0,...activeCredit.map(x=>N(x.daysPastDue))),hardPenalty=18*N(s.lateShort)+75*N(s.late30)+100*N(s.late60)+135*N(s.late90)+165*N(s.late120);
 const historyPenalty=8*N(s.lateOlder)+12*N(s.restructure)+6*N(s.refinance)+clamp(40*N(s.collections)+65*N(s.chargeOffs)+40*N(s.judicial),0,125);
 parts.payment=[
  part('p_recent','Puntualidad reciente',clamp(235-hardPenalty,0,235),235,`${s.lateShort} demoras 1–29d · ${s.late30} de 30–59d · ${s.late60} de 60–89d`, '235 − 18·moras(1–29) − 75·moras(30–59) − 100·moras(60–89) − 135·moras(90–119) − 165·moras(120+); mínimo 0.'),
  part('p_history','Antecedentes, cobranza y castigos',clamp(80-historyPenalty,0,80),80,`Antecedentes antiguos: ${s.lateOlder}; reestructuraciones: ${N(s.restructure)}; refinanciamientos: ${N(s.refinance)}; cobranza: ${s.collections}; castigos: ${s.chargeOffs}`,'80 − 8·moras antiguas − 12·reestructuraciones(24m) − 6·refinanciamientos(24m) − 40·cobranzas − 65·castigos − 40·incidencias judiciales, limitado a 0–80.'),
  part('p_dpd','Atraso vigente',clamp(35-lerp(dpd,[[0,0],[1,8],[29,15],[30,22],[60,28],[90,35]]),0,35),35,`${dpd} días de atraso máximo en obligaciones activas`,'35 menos penalidad de severidad de mora máxima observada al corte; interpolación en 0,1,29,30,60,90 días. Una misma mora puede reflejarse en vigencia e historial como mecanismos diferentes.')
 ];
 const totalLimit=cards.reduce((a,c)=>a+c.limitD,0),totalBal=cards.reduce((a,c)=>a+c.balanceD,0),util=totalLimit>0?totalBal/totalLimit:null,peak=Math.max(0,...cards.filter(c=>c.limitD>0).map(c=>c.balanceD/c.limitD)),hi=cards.filter(c=>c.limitD>0&&c.balanceD/c.limitD>=.75).length,over=cards.filter(c=>c.limitD>0&&c.balanceD/c.limitD>1).length;
 const totals=cards.reduce((a,c)=>a+c.advanceD,0),advShare=totalBal>0?totals/totalBal:0;
 const weightedLoanProgress=s.loans.filter(l=>l.status!=='closed').length? s.loans.filter(l=>l.status!=='closed').reduce((a,l)=>a+N(l.original)*clamp(1-N(l.balance)/Math.max(N(l.original),1),0,1),0)/s.loans.filter(l=>l.status!=='closed').reduce((a,l)=>a+N(l.original),0) :null;
 parts.owed=[
  part('o_aggregate','Uso agregado de tarjetas',util===null?135:lerp(util,[[0,180],[.01,180],[.09,177],[.29,148],[.49,110],[.75,60],[1,12],[1.2,0]]),180,util===null?'Sin líneas revolventes':`${pct(util)} (saldo ${cash(totalBal)} / límite ${cash(totalLimit)})`,'180 puntos máximos: <=1% 180; 9% 177; 29% 148; 49% 110; 75% 60; 100% 12; >=120% 0. Interpolación lineal.'),
  part('o_peak','Tarjeta más utilizada',cards.length?45-clamp((peak-.30)*65,0,45):35,45,`${pct(peak)} de utilización máxima`,'45 − min(45, máx(0, utilización máxima − 30%) × 65). Penalización por concentración.'),
  part('o_limits','Tarjetas tensionadas / sobrelímite',clamp(25-hi*6-over*12,0,25),25,`${hi} al 75% o más · ${over} sobre el límite`,'25 − 6 por tarjeta >=75% − 12 por tarjeta sobre 100%; mínimo 0.'),
  part('o_installments','Avance en amortización',weightedLoanProgress===null?26:12+23*weightedLoanProgress,35,weightedLoanProgress===null?'Sin préstamos activos':`${pct(weightedLoanProgress)} del principal original amortizado`,'Si hay préstamos: 12 + 23 × proporción ponderada de capital amortizado; sin préstamos: valor neutral 26.'),
  part('o_cashadvance','Exposición a avances de efectivo',15-clamp((totalLimit>0?totals/totalLimit:0)/.25*15,0,15),15,`${pct(totalLimit>0?totals/totalLimit:0)} de los límites totales está expuesto a avances`,'15 − min(15, (avances vigentes / límites totales) ÷ 25% × 15). Regla prudencial PROPIA, no factor publicado por burós; no penaliza amortizar compras mientras el avance permanezca fijo.')
 ];
 const oldest=N(s.historyMonths),avg=N(s.avgHistoryMonths||s.historyMonths*.70),depth=N(s.recordMonths);
 parts.age=[
  part('a_old','Cuenta más antigua',75*clamp(oldest/120,0,1),75,`${oldest} meses`,'75 × min(antigüedad del producto más antiguo / 120, 1).'),
  part('a_avg','Antigüedad promedio',45*clamp(avg/84,0,1),45,`${avg} meses`,'45 × min(antigüedad media / 84, 1).'),
  part('a_depth','Profundidad de evidencia',30*clamp(depth/24,0,1),30,`${depth} meses de datos útiles`,'30 × min(meses con evidencia / 24, 1). Sin crear historial si el dato es desconocido.')
 ];
 parts.new=[
  part('n_new','Aperturas recientes de productos',clamp(60-15*N(s.new0to6)-6*N(s.new7to12),0,60),60,`${s.new0to6} (0–6m) · ${s.new7to12} (7–12m)`,'60 − 15·aperturas(0–6m) − 6·aperturas(7–12m); mínimo 0. Cuenta tarjetas y préstamos (también los cerrados) según su mes y año de apertura: 0–6 meses y 7–12 meses, sin superponerse.'),
  part('n_limit','Aumentos de límite solicitados',clamp(40-8*N(s.limitReq0to6)-3*N(s.limitReq7to12),0,40),40,`${N(s.limitReq0to6)} (0–6m) · ${N(s.limitReq7to12)} (7–12m) solicitados`,'40 − 8·aumentos solicitados(0–6m) − 3·aumentos solicitados(7–12m); mínimo 0. Los aumentos automáticos no se penalizan.')
 ];
 const hasCards=cards.length>0,hasLoans=s.loans.some(l=>l.status!=='closed');
 parts.mix=[
  part('m_active','Gestión de productos existentes',activeCredit.length?65:0,65,`${cards.length} tarjetas · ${s.loans.length} préstamos`,'65 puntos cuando existe historial de producto activo. No recompensa el volumen de cuentas.'),
  part('m_types','Combinación y experiencia',hasCards&&hasLoans?35:hasCards||hasLoans?28:0,35,hasCards&&hasLoans?'Revolvente + cuotas':'Un tipo de crédito','35 si ambos tipos ya existen; 28 con solo uno. No abrir crédito por obtener estos 7 puntos de diferencia.')
 ];
 const points=Object.fromEntries(FACTORS.map(f=>[f.id,parts[f.id].reduce((a,p)=>a+p.points,0)]));const score=major.length||activeCredit.length===0?null:Object.values(points).reduce((a,v)=>a+v,0);
 const capacity=affordability(s);
 return {parts,points,score,cards,activeCredit,errors,totalLimit,totalBal,util,peak,hi,over,advShare,weightedLoanProgress,capacity,dpd};
}
function affordability(s,settings=DB.settings){
 const w=settings.informal?.[s.informalQuality]??0,recurrence=clamp(N(s.informalMonths)/6,0,1),recognizedInformal=N(s.informal)*w*recurrence;
 const baseFormal=N(s.formal)*(s.formalVerified?(N(s.formalMonths)<3?.85:1):.70), formal=baseFormal+(s.formalVerified?N(s.otherFormal):N(s.otherFormal)*.65),income=formal+recognizedInformal;
 const cardDues=s.cards.filter(c=>c.status!=='closed').reduce((a,c)=>a+conversion(Math.min(N(c.min),Math.max(N(c.balance),N(c.min))),c.currency,s),0);
 const loanDues=s.loans.filter(l=>l.status!=='closed').reduce((a,l)=>a+conversion(l.due,l.currency||'DOP',s),0),debt=cardDues+loanDues;
 const cashFixed=s.expenses.filter(e=>!e.onCard).reduce((a,e)=>a+N(e.amount),0),covered=s.expenses.filter(e=>e.onCard).reduce((a,e)=>a+N(e.amount),0);
 const obligations=debt+cashFixed+covered,dti=income>0?debt/income:null,margin=income-obligations,needed=Math.max(settings.floor||0,income*(settings.reserve||0)),safe=margin-needed;
 const dtiRoom=income>0?settings.dti*income-debt:0,newQuota=income>0?Math.max(0,Math.min(dtiRoom,safe)):0;
 const stressIncome=formal*.80+recognizedInformal*.50;const usdDebt=s.cards.filter(c=>c.currency==='USD').reduce((a,c)=>a+conversion(c.min,c.currency,s),0)+s.loans.filter(l=>l.currency==='USD').reduce((a,l)=>a+conversion(l.due,l.currency,s),0);
 const variableRateShock=s.loans.filter(l=>l.variable&&l.status!=='closed').reduce((a,l)=>a+conversion(l.balance,l.currency||'DOP',s)*.02/12,0);
 const stressDebt=debt+usdDebt*.10+variableRateShock,stressDti=stressIncome>0?stressDebt/stressIncome:null;
 const stressMargin=stressIncome-stressDebt-cashFixed-covered;
 return {formal,recognizedInformal,income,cardDues,loanDues,debt,cashFixed,covered,obligations,dti,margin,needed,safe,dtiRoom,newQuota,stressIncome,stressDebt,stressDti,stressMargin,variableRateShock,w,recurrence};
}
function validate(s){const out=[],put=(level,text)=>out.push({level,text});if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(s.period||''))put('critical','Período inválido.');if(!Number.isFinite(N(s.txRate))||N(s.txRate)<=0)put('critical','Tasa DOP/USD inválida.');for(const k of ['historyMonths','avgHistoryMonths','recordMonths','lateShort','late30','late60','late90','late120','new0to6','new7to12','limitReq0to6','limitReq7to12'])if(!Number.isFinite(+s[k])||+s[k]<0)put('critical','Campo inválido: '+k);
 if(!s.cards?.length&&!s.loans?.length)put('critical','No se registró ninguna obligación crediticia.');{const late=(s.cards||[]).concat(s.loans||[]).filter(x=>N(x.daysPastDue)>0&&x.status!=='closed');if(late.length)put('warning',`vive el hoy detecta vencimientos sin pagar en ${late.map(x=>x.name).join(', ')}. Si ya los pagaste, concílialos en la app: la mora vigente se calcula con esos vencimientos.`)}
 const ids=new Set();for(let c of s.cards||[]){if(ids.has(c.id))put('critical','Tarjeta duplicada: '+c.name);ids.add(c.id);if(!['DOP','USD'].includes(c.currency))put('critical','Moneda no admitida en '+c.name);if(!Number.isFinite(+c.limit)||c.limit<=0||N(c.balance)<0||N(c.min)<0)put('critical','Límite, saldo o mínimo inválido en '+c.name);if(N(c.advance)>N(c.balance))put('warning','Avances superiores al saldo informado en '+c.name);if(N(c.balance)>N(c.limit))put('warning',c.name+' supera su límite disponible.');if(!c.reportedAt)put('warning',c.name+' sin fecha de saldo reportado; podrías estar mezclando períodos.');}
 for(let l of s.loans||[]){if(ids.has(l.id))put('critical','Crédito duplicado: '+l.name);ids.add(l.id);if(N(l.original)<=0||N(l.balance)<0||N(l.due)<0)put('critical','Principal, balance o cuota inválida de '+l.name);if(N(l.balance)>N(l.original))put('warning',l.name+' tiene saldo superior al principal original (capitalización o dato a revisar).');}
 if(N(s.recordMonths)<12)put('warning','Historial observado en construcción (desde noviembre de 2026): confianza limitada.');(s.missing||[]).forEach(m=>put('critical',m));if(N(s.formal)+N(s.informal)+N(s.otherFormal)<=0)put('warning','No hay ingresos recurrentes registrados: la capacidad de pago queda indeterminada, aunque el score crediticio puede calcularse.');if(s.informal>0&&s.informalQuality==='self')put('info','El ingreso informal autodeclarado se reconoce parcialmente para capacidad; no suma puntos al score.');if((s.expenses||[]).some(e=>e.onCard))put('info','Gastos marcados como cubiertos por tarjeta se excluyen del gasto fijo externo; verifica que realmente estén incluidos en los pagos de tarjeta.');
 return out;
}
function compare(i=idx){let c=evaluate(DB.months[i]),p=i>0?evaluate(DB.months[i-1]):null,diff={},partDiff={};for(let f of FACTORS){diff[f.id]=p?c.points[f.id]-p.points[f.id]:0;partDiff[f.id]=c.parts[f.id].map((v,j)=>({...v,delta:p?v.points-p.parts[f.id][j].points:0}));}return {c,p,diff,partDiff,delta:p&&p.score!==null&&c.score!==null?c.score-p.score:null};}
function scoreName(x){return x===null?'Datos insuficientes':x>=850?'Perfil de crédito muy sólido':x>=750?'Perfil de crédito sólido':x>=620?'Perfil en desarrollo':x>=470?'Requiere atención':'Atención prioritaria'}
function whyFactor(id,c,p){if(id==='payment')return `Atrasos vigentes: ${c.dpd} días. Las moras se contabilizan por severidad y ventana histórica, no por ingreso.`;if(id==='owed')return `Uso global ${pct(c.util)}${p?', frente a '+pct(p.util):''}. Pico por tarjeta ${pct(c.peak)}. Avances incluidos en saldos ${pct(c.advShare)}.`;if(id==='age')return 'Cambian los meses de antigüedad y profundidad documentada del historial.';if(id==='new')return 'Aperturas de productos nuevos y aumentos de límite solicitados en ventanas de 0–6 y 7–12 meses.';return 'Combinación de tipos de crédito ya existentes. No abras crédito innecesariamente.';}
function narrative(i=idx){const x=compare(i),c=x.c,s=DB.months[i];if(c.score===null)return 'No es posible calcular un puntaje confiable con las inconsistencias críticas actuales. Corrige las alertas de calidad y vuelve a evaluar.';if(!x.p)return `Esta es tu primera fotografía crediticia: utilizas ${pct(c.util)} de tus líneas y tu obligación mensual contractual es ${cash(c.capacity.debt)}. Aquí no aparecen causas de cambio porque aún no existe un corte comparable.`;
 let arr=FACTORS.map(f=>({...f,delta:x.diff[f.id]})).sort((a,b)=>Math.abs(b.delta)-Math.abs(a.delta)),pos=arr.filter(o=>o.delta>0),neg=arr.filter(o=>o.delta<0);let direction=x.delta>0?`Tu VIVE SCORE CRÉDITO subió ${x.delta} puntos.`:x.delta<0?`Tu VIVE SCORE CRÉDITO bajó ${Math.abs(x.delta)} puntos.`:'Tu VIVE SCORE CRÉDITO se mantuvo sin cambios.';
 let p=pos.length?' Te favoreció '+pos.slice(0,2).map(o=>o.name.toLowerCase()+` (+${o.delta})`).join(' y ')+'.':' No hubo factores con incremento positivo.';
 let n=neg.length?' En contra actuó '+neg.slice(0,2).map(o=>o.name.toLowerCase()+` (${o.delta})`).join(' y ')+'.':' Ningún factor descontó puntos este período.';
 let prev=DB.months[i-1],detail=` La utilización total ${c.util!==null?`es ${pct(c.util)}`:'no está disponible'}${x.p.util!==null?` (antes ${pct(x.p.util)})`:''}.`;
 let watch=c.capacity.income>0?` Fuera del score, tus cuotas representan ${pct(c.capacity.dti)} del ingreso reconocido y el margen mensual calculado es ${cash(c.capacity.margin)}.`:' La capacidad de endeudamiento requiere ingresos reconocidos.';
 return direction+p+n+detail+watch+' Estos movimientos son del modelo VIVE, no estimaciones de puntos TransUnion o Equifax.';
}
function auditLog(action){auditHistory.unshift({at:new Date().toISOString(),action,engine:ENGINE,period:current()?.period||''});auditHistory=auditHistory.slice(0,200);ST.audit=auditHistory;saveStore()}
function tag(text,type='neutral'){return `<span class="tag ${type}">${safe(text)}</span>`}
function sec(title,sub='',aside=''){return `<div class="sectionTop"><div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${aside}</div>`}
function factCard(f,x){let n=x.c.points[f.id],d=x.diff[f.id];return `<button type="button" data-factor="${f.id}" class="card factorcard"><div class="hrow"><h3><span class="ficon">${f.icon}</span> ${f.name}</h3><b class="monoValue">${n} <small class="muted">/ ${f.max}</small></b></div><div class="meter"><span style="width:${100*n/f.max}%"></span></div><div class="fmeta"><span>${f.tag} del modelo</span><strong class="${cls(d)}">${x.p?sign(d)+' pts':'Primer corte'}</strong></div><div class="muted sm">${f.about}</div></button>`}
function kpi(label,value,note,klass=''){return `<div class="card stat"><div class="caps">${label}</div><div class="statVal ${klass}">${value}</div><p>${note}</p></div>`}
function statusPill(c){return `<span class="statusChip ${c.score>=750?'good':c.score<620?'bad':''}">${c.score===null?'Incompleto':c.score>=750?'◉ Bien encaminado':'◌ Revisar factores'}</span>`}
function scoreBlock(i=idx){let x=compare(i),c=x.c;return `<div class="card scoreHero"><div class="ring" style="--percent:${c.score===null?0:c.score/10}%"><div class="ringInside"><div class="bigNumber monoValue">${c.score??'—'}</div><div class="bigSub">de 1,000 puntos</div></div></div><div class="heroDetails"><div class="caps">VIVE SCORE CRÉDITO · ${safe(monthLabel(DB.months[i].period))}</div><h2>${scoreName(c.score)}</h2><div class="movement ${cls(x.delta||0)}">${x.p&&x.delta!==null?(x.delta>0?'↗ ':x.delta<0?'↘ ':'→ ')+sign(x.delta)+' puntos':'Corte inicial / sin comparación'}</div><p>Motor v${ENGINE}. Cinco factores crediticios; los ingresos se analizan en otro módulo.</p><div style="margin-top:12px">${statusPill(c)}</div><div class="chipRow" style="margin-top:15px"><button class="smallbtn" data-tab="evolution">Explorar evolución ↗</button></div></div></div>`}
function textBlock(i=idx){const c=evaluate(DB.months[i]);return `<div class="card"><div class="hrow"><div><div class="caps">RESUMEN AUTOMÁTICO · EXPLICACIÓN REPRODUCIBLE</div><h2 style="margin-top:8px">Tu score, explicado.</h2></div><span class="inlineIcon sparkle">✧</span></div><div class="smallDivider"></div><p class="narrative">${safe(narrative(i))}</p><div class="hrow wrapMobile"><span class="muted xs">El texto usa factores verificables, sin atribuir variaciones a los burós.</span><button class="smallbtn" data-tab="evolution">Ver causas ↗</button></div></div>`}
function dataWarnings(s=current()){const ev=evaluate(s);return ev.errors.length?`<div class="warnings">${ev.errors.map(w=>`<div class="witem ${w.level}"><span>${w.level==='critical'?'✕':w.level==='warning'?'!':'i'}</span><div>${safe(w.text)}</div></div>`).join('')}</div>`:`<div class="okMessage">✓ Sin alertas de integridad detectadas por las validaciones de este prototipo.</div>`}
function factorList(i=idx){let x=compare(i);return `<div class="grid factors">${FACTORS.map(f=>factCard(f,x)).join('')}</div>`}
function reasonRows(i=idx){const x=compare(i);return `<div class="card"><div class="hrow"><div><div class="caps">CONCILIACIÓN DEL CAMBIO</div><h2 style="margin-top:8px">Cada punto tiene una causa</h2></div>${tag('Σ Δ factores = Δ total')}</div><div class="smallDivider"></div>${FACTORS.map(f=>`<button class="reasonRow" data-factor="${f.id}"><span>${f.icon} ${f.name}</span><strong class="${cls(x.diff[f.id])}">${x.p?sign(x.diff[f.id])+' pts':'—'}</strong><span class="muted">↗</span></button>`).join('')}<div class="reasonTotal"><span>Variación reconciliada</span><b class="${cls(x.delta||0)}">${x.delta!==null?sign(x.delta)+' pts':'Primer corte'}</b></div><p class="muted xs">La comparación usa la misma versión de fórmula para ambos cortes. Si el modelo cambia, se debe recalcular todo el historial y registrar la versión.</p></div>`}
function financeBox(i=idx){let c=evaluate(DB.months[i]),a=c.capacity;return `<div class="card"><div class="caps">UNA SEGUNDA LECTURA, NO EL SCORE</div><h2 style="margin-top:8px">Capacidad para una nueva cuota.</h2><p>Ingresos y gastos fijos ayudan a identificar margen de endeudamiento; nunca aumentan directamente los puntos de crédito.</p><div class="metricList"><div class="metricLine"><span>Ingresos formales + informales ponderados</span><b>${cash(a.income)}</b></div><div class="metricLine"><span>Cuotas de crédito al mes</span><b>${cash(a.debt)}</b></div><div class="metricLine"><span>Gastos fijos externos a tarjetas</span><b>${cash(a.cashFixed)}</b></div><div class="metricLine"><span>Cuota nueva orientativa máxima</span><b>${cash(a.newQuota)}</b></div></div><button class="btn green" data-tab="capacity">Evaluar capacidad ↗</button></div>`}
function cardTable(i=idx){const s=DB.months[i],cards=eqCards(s);if(!cards.length)return `<p class="muted">Sin tarjetas activas.</p>`;return `<div class="tblscroll"><table class="tbl"><thead><tr><th>Tarjeta</th><th>Balance</th><th>Límite</th><th>Uso</th><th>Avance incluido</th><th>Acción</th></tr></thead><tbody>${cards.map(c=>`<tr><td><b>${safe(c.name)}</b><div class="muted xs">${c.currency} · ${(c.status==='closed'?'Cerrada':'Activa')}</div></td><td>${cash(c.balance,c.currency)}</td><td>${cash(c.limit,c.currency)}</td><td>${pct(c.balance/c.limit)}</td><td>${cash(c.advance,c.currency)}</td><td><button class="rowBtn" data-card="${safe(c.id)}">Analizar ↗</button></td></tr>`).join('')}</tbody></table></div>`}
function summary(){let c=compare(idx).c,a=c.capacity;return `${dataWarnings(current()).includes('critical')?'<div class="callout">Los datos críticos pueden impedir calcular el índice. Revisa la pestaña Auditoría.</div>':''}<div class="grid heroGrid">${scoreBlock()}${textBlock()}</div><div class="grid stats">${kpi('Utilización revolving',pct(c.util),`${cash(c.totalBal)} utilizados / ${cash(c.totalLimit)} de límite`)}${kpi('Mayor uso individual',pct(c.peak),`${c.hi} tarjeta(s) ≥75%`)}${kpi('Días de mora vigente',fmt(c.dpd),'Máximo entre obligaciones activas',c.dpd>0?'neg':'')}${kpi('Presión contractual',a.dti===null?'—':pct(a.dti),'Cuotas / ingresos reconocidos · fuera del score')}</div>${sec('Los cinco pilares del score','35 / 30 / 15 / 10 / 10: pesos educativos de referencia, adaptados a reglas propias explícitas.','<button class="smallbtn" data-tab="method">Ver metodología ↗</button>')}${factorList()}${sec('Radiografía de este mes','Explicación y capacidad conectadas, pero puntuadas por separado.') }<div class="grid pair">${reasonRows()}${financeBox()}</div>${sec('Todas tus tarjetas','El avance de efectivo ya está contenido en el saldo utilizado.') }<div class="card">${cardTable()}<div class="callout"><b>Regla estructural:</b> las cuentas de ahorro, el patrimonio, el ingreso formal y las suscripciones NO entran directamente en los cinco factores del score. Los ingresos y gastos sirven únicamente para capacidad de pago y recomendaciones.</div></div>`}
function trendSvg(){let pts=DB.months.map(m=>evaluate(m).score),n=pts.length,w=960,h=240,p=34,nonnull=pts.filter(v=>v!==null);if(!nonnull.length)return '<p>Sin puntajes válidos.</p>';let low=Math.max(0,Math.min(...nonnull)-42),high=Math.min(1000,Math.max(...nonnull)+42),span=Math.max(1,high-low);let arr=pts.map((v,i)=>({x:p+(w-2*p)*(n===1?.5:i/(n-1)),y:v===null?null:20+(h-50)*(1-(v-low)/span)}));let path=arr.filter(a=>a.y!==null).map(a=>a.x+','+a.y).join(' ');return `<svg class="graphbox" viewBox="0 0 ${w} ${h}" role="img" aria-label="Evolución del VIVE SCORE, selecciona un mes con los botones inferiores"><defs><linearGradient id="fadeV3" x1="0" y1="0" x2="0" y2="1"><stop style="stop-color:var(--teal)" stop-opacity=".19"/><stop offset="1" style="stop-color:var(--teal)" stop-opacity="0"/></linearGradient></defs>${[.25,.5,.75].map(z=>`<line x1="${p}" y1="${20+(h-50)*z}" x2="${w-p}" y2="${20+(h-50)*z}" stroke="var(--line)" stroke-dasharray="3,6"/>`).join('')}${n>1?`<polygon points="${p},${h-30} ${path} ${w-p},${h-30}" fill="url(#fadeV3)"/>`:''}<polyline points="${path}" fill="none" stroke="var(--teal)" stroke-width="4" stroke-linecap="round" stroke-linejoin="round"/>${arr.map((a,j)=>a.y===null?'':`<circle data-graph-month="${j}" tabindex="0" role="button" aria-label="Ver ${safe(monthLabel(DB.months[j].period))}: ${pts[j]} puntos" cx="${a.x}" cy="${a.y}" r="${j===idx?8:6}" fill="var(--teal)" stroke="var(--paper)" stroke-width="3" style="cursor:pointer"><title>${safe(monthLabel(DB.months[j].period))}: ${pts[j]} puntos</title></circle>`).join('')}</svg>`}
function monthSelect(){return `<div class="pointlist">${DB.months.map((m,i)=>{let c=evaluate(m),p=i?evaluate(DB.months[i-1]):null,d=p&&c.score!==null&&p.score!==null?c.score-p.score:null;return `<button data-month="${i}" class="monthBtn ${i===idx?'active':''}" aria-pressed="${i===idx}"><small>${safe(tinyMonth(m.period))} ${m.period.slice(2,4)}</small><b>${c.score??'—'}</b><span class="${cls(d||0)}">${d===null?'—':sign(d)+' pts'}</span></button>`}).join('')}</div>`}
function drivers(i=idx){let x=compare(i);return `<div class="card"><div class="caps">DESGLOSE MATEMÁTICO DEL MES</div><h2 style="margin:8px 0 14px">${safe(monthLabel(DB.months[i].period))}: ${x.delta!==null?sign(x.delta)+' puntos':'primer corte'}</h2>${FACTORS.map(f=>{let d=x.diff[f.id];return `<button class="reasonItem" data-factor="${f.id}"><div class="causeNum ${cls(d)}">${d>0?'↗':d<0?'↘':'→'}</div><div class="causeMain"><b>${f.name}</b><p>${safe(whyFactor(f.id,x.c,x.p))}</p><div class="microPoints">${x.partDiff[f.id].map(q=>`<span>${safe(q.label)}: ${sign(q.delta)}</span>`).join('')}</div></div><strong class="${cls(d)}">${x.p?sign(d):'—'}</strong></button>`}).join('')}<div class="reasonTotal"><span>Total exacto</span><strong>${x.delta===null?'—':sign(x.delta)} pts</strong></div></div>`}
function cardAttribution(i=idx){if(i===0)return '<div class="card"><p>Necesitas al menos dos meses para repartir los cambios por tarjeta.</p></div>';let a=DB.months[i-1],b=DB.months[i],before=evaluate(a),after=evaluate(b),allIds=[...new Set(a.cards.concat(b.cards).map(c=>c.id))];if(allIds.length>16)return `<div class="card">Atribución exacta por tarjeta no calculada: demasiados instrumentos. Consulta las variaciones por factor.</div>`;
 // Shapley exact up to 10 cards; beyond that two deterministic permutations approximate.
 const prev=new Map(a.cards.map(c=>[c.id,c])),now=new Map(b.cards.map(c=>[c.id,c]));
 function value(mask){let copy=clone(b);copy.cards=allIds.map((id,k)=>mask&(1<<k)?now.get(id):prev.get(id)).filter(Boolean).map(clone);return evaluate(copy).points.owed}
 const n=allIds.length,full=(1<<n)-1,values=[],results=[];
 if(n<=10){for(let mask=0;mask<=full;mask++)values[mask]=value(mask);let fact=[1];for(let k=1;k<=n;k++)fact[k]=fact[k-1]*k;for(let k=0;k<n;k++){let val=0;for(let mask=0;mask<=full;mask++){if(mask&(1<<k))continue;let bits=0,z=mask;while(z){z&=z-1;bits++}val+=(values[mask|1<<k]-values[mask])*fact[bits]*fact[n-bits-1]/fact[n];}results.push({id:allIds[k],val})}}
 else {let curr=0,parts=new Map(allIds.map(id=>[id,0]));for(let order of [allIds,allIds.slice().reverse()]){let mask=0,last=value(0);for(let id of order){mask|=1<<allIds.indexOf(id);let next=value(mask);parts.set(id,parts.get(id)+(next-last)/2);last=next}}results.push(...allIds.map(id=>({id,val:parts.get(id)})))}
 const total=(after.points.owed-before.points.owed),fromCards=results.reduce((a,b)=>a+b.val,0),remainder=total-fromCards;
 return `<div class="card"><div class="hrow"><h2>Atribución de deuda y uso</h2><b class="${cls(total)}">${sign(total)} pts</b></div><p class="muted sm">La atribución reparte matemáticamente el cambio del factor «Deuda y utilización» entre las tarjetas. No describe cómo un buró reparte puntos.</p><div class="metricList">${results.sort((a,b)=>Math.abs(b.val)-Math.abs(a.val)).map(z=>{const c=now.get(z.id)||prev.get(z.id);return `<div class="metricLine"><span>${safe(c.name)}</span><b class="${cls(z.val)}">${sign(+z.val.toFixed(2))} pts</b></div>`}).join('')}<div class="metricLine"><span>Otros cambios (préstamos, moneda y parámetros)</span><b>${sign(+remainder.toFixed(2))} pts</b></div></div><div class="callout">${n<=10?'Método exacto de Shapley, sin redondeos intermedios.':'Aproximación por dos órdenes; verificar con un motor analítico para alta dimensionalidad.'} El residual conserva la conciliación con el cambio total.</div></div>`;
}
function eventsView(i=idx){let s=DB.months[i];return `<div class="card"><div class="hrow wrapMobile"><div><h2>Evidencias del período</h2><p>Registro de eventos anotados por ti. Un evento no se puntúa dos veces si ya alteró el saldo o la mora del corte.</p></div><button class="smallbtn" data-tab="data">Editar evidencias ↗</button></div>${s.events?.length?s.events.map(e=>`<div class="metricLine"><span><b>${safe(e.date)}</b> · ${safe(e.label)}<div class="muted xs">${safe(e.note||'Sin nota')} · ${safe(e.type)}</div></span>${tag('Referencia')}</div>`).join(''):'<p>No hay eventos agregados.</p>'}</div>`}
function externalView(i=idx){let s=DB.months[i],p=i?DB.months[i-1]:null;let metric=(name,key,range)=>`<div class="card"><div class="caps">${name}</div><div class="statVal">${s[key]??'—'}</div><p>${range}. ${s[key]!==null&&p?.[key]!=null?'Cambio informado '+sign(s[key]-p[key])+' puntos (otra escala).':'Sin comparación externa confirmada.'}</p></div>`;return `<div class="grid pair">${metric('TransUnion Tu Score RD','reportedTU','Escala pública 459–848')}${metric('Equifax / DataCrédito','reportedEquifax','Modelo/escala externos por verificar')}</div><div class="callout">Estos valores solo se registran manualmente tras obtenerlos del proveedor. VIVE SCORE no predice ni infiere el puntaje del buró. Si un buró cambia en dirección diferente, revisa fechas de reporte, fuente y modelo utilizado.</div>`}
function evolution(){return `${sec('La historia completa de tu score','Selecciona cualquier período y descubre qué dato cambió, qué regla se activó y cuántos puntos generó.') }<div class="card graphCard"><div class="hrow wrapMobile"><div><div class="caps">${DB.months.length} ${DB.months.length===1?'CORTE OBSERVADO':'CORTES OBSERVADOS'} · DESDE ${safe(monthLabel(DB.months[0].period).toUpperCase())}</div><h2 style="margin-top:6px">${safe(monthLabel(current().period))} · ${evaluate(current()).score??'—'} pts</h2></div>${tag('Toque un mes')}</div>${trendSvg()}${monthSelect()}</div>${sec('Tu mes, en palabras','Resumen humano generado desde los cambios reales del modelo.') }<div class="grid pair">${textBlock()}${drivers()}</div>${sec('Quién modificó los puntos','Desglose de tarjetas y evidencias; consulta información del período seleccionado.')}<div class="grid pair">${cardAttribution()}${eventsView()}</div>${sec('Comparador con el buró','Compara tendencias únicamente si has introducido valores oficiales observados.')}${externalView()}`}
function recentBlock(s){const L=(s.products||[]);if(!L.length)return '';const rows=L.slice().sort((a,b)=>(b.opened||'').localeCompare(a.opened||'')).map(p=>`<tr><td><b>${safe(p.name)}</b><div class="muted xs">${p.kind==='card'?'Tarjeta':'Préstamo'}${p.bank?' · '+safe(p.bank):''}${p.unrated?' · sin límite ni saldo':''}${p.closed?' · cerrado':''}</div></td><td>${p.opened?safe(myLabel(p.opened)):'—'}</td><td>${p.age===null?'—':p.age+' meses'}</td><td><span class="tag ${p.window==='0–6 meses'||p.window==='7–12 meses'?'warn':p.window==='falta la fecha'?'bad':''}">${safe(p.window)}</span></td><td>${safe(p.source)}</td></tr>`).join('');return `${sec('Créditos recientes','Cada tarjeta y préstamo con su mes y año de apertura (leído de «Editar» en vive el hoy). Los de 0–6 y 7–12 meses restan en «Crédito reciente».')}<div class="card"><div class="metricList"><div class="metricLine"><span>Aperturas de 0 a 6 meses</span><b>${s.new0to6}</b></div><div class="metricLine"><span>Aperturas de 7 a 12 meses</span><b>${s.new7to12}</b></div></div><div class="tblscroll"><table class="tbl"><thead><tr><th>Producto</th><th>Apertura</th><th>Edad</th><th>Cuenta como</th><th>Origen de la fecha</th></tr></thead><tbody>${rows}</tbody></table></div><p class="xs muted">Si un producto dice «falta la fecha», ponla en Editar (mes y año en que lo adquiriste) o en Configuración y antecedentes; sin fecha no puede contarse.</p></div>`}
function credits(){let c=evaluate(current()),s=current();let loans=s.loans.map(l=>`<tr><td><b>${safe(l.name)}</b><div class="muted xs">${safe(l.type||'préstamo')} · ${safe(l.currency||'DOP')}</div></td><td>${cash(l.balance,l.currency||'DOP')}</td><td>${cash(l.original,l.currency||'DOP')}</td><td>${cash(l.due,l.currency||'DOP')}</td><td>${pct(clamp(1-N(l.balance)/Math.max(1,N(l.original)),0,1))}</td><td><button class="rowBtn" data-loan="${safe(l.id)}">Analizar ↗</button></td></tr>`).join('');return `${sec('Todos tus instrumentos crediticios','Balances y límites en moneda original; conversión a RD$ únicamente para agregados.') }<div class="grid stats">${kpi('Límites de tarjetas',cash(c.totalLimit),'Equivalentes RD$ con tasa del corte')}${kpi('Balances revolving',cash(c.totalBal),pct(c.util)+' de utilización agregada')}${kpi('Avances de efectivo',cash(c.cards.reduce((a,b)=>a+b.advanceD,0)),'Incluidos en saldos, nunca otra deuda')}${kpi('Deuda cuotas',cash(s.loans.reduce((a,l)=>a+conversion(l.balance,l.currency||'DOP',s),0)),'Saldo pendiente del principal')}</div>${sec('Tarjetas de crédito','Abre para revisar sobrelímites, cortes, mínimo y avances.') }<div class="card">${cardTable()}</div>${sec('Préstamos y financiamientos','La amortización se calcula contra el principal original, no contra el límite revolving.') }<div class="card"><div class="tblscroll"><table class="tbl"><thead><tr><th>Crédito</th><th>Saldo</th><th>Principal</th><th>Cuota</th><th>Amortización</th><th>Detalle</th></tr></thead><tbody>${loans||'<tr><td colspan="6">No hay préstamos.</td></tr>'}</tbody></table></div></div>${recentBlock(s)}${sec('Señales a monitorear','El valor de un avance de efectivo se refleja en la tarjeta; su clasificación separada es una regla interna, no del buró.') }<div class="card">${dataWarnings(s)}</div>`}
function metricPair(t,v,ex){return `<div class="metricLine"><span>${t}<div class="muted xs">${ex||''}</div></span><b>${v}</b></div>`}
function capacityBase(){const a=affordability(current()),s=current(),settings=DB.settings;return `${sec('Capacidad realista de endeudamiento','Sin cuentas de ahorro, sin patrimonio y sin modificar el score de crédito. Ingresos netos, obligaciones y gastos fijos.') }<div class="grid stats">${kpi('Ingreso reconocido',cash(a.income),'Neto formal + informal ajustado por evidencia')}${kpi('Ratio de deuda',a.dti===null?'—':pct(a.dti),'Cuotas contractuales / ingresos reconocidos')}${kpi('Margen mensual',cash(a.margin),'Después de cuotas, gastos fijos y consumos recurrentes en tarjeta',a.margin<0?'neg':'')}${kpi('Nueva cuota orientativa',cash(a.newQuota),`Objetivo DTI ${(settings.dti*100).toFixed(0)}% y reserva precautoria`)}</div>${sec('De dónde sale cada peso','Separa deuda exigible presente de gastos recurrentes futuros, también cuando se cargan a tarjeta.') }<div class="grid pair"><div class="card"><h2>Ingresos admitidos</h2><div class="metricList">${metricPair('Nómina neta formal',cash(s.formal),'Utilizar neto luego de ISR, AFP, ARS y descuentos para no duplicar deducciones')}${metricPair('Otras rentas formales',cash(s.otherFormal),'Si no están verificadas se considera el 65% como criterio propio')}${metricPair('Ingreso informal bruto',cash(s.informal),`${s.informalMonths} meses de recurrencia declarada`)}${metricPair('Ingreso informal reconocido',cash(a.recognizedInformal),`${(a.w*100).toFixed(0)}% por calidad × ${(a.recurrence*100).toFixed(0)}% por recurrencia`)}${metricPair('Total reconocido',cash(a.income),'Solo para capacidad y recomendaciones')}</div></div><div class="card"><h2>Compromisos reales</h2><div class="metricList">${metricPair('Pagos mínimos de tarjetas',cash(a.cardDues),'En moneda convertida a RD$')}${metricPair('Cuotas de préstamos',cash(a.loanDues),'Incluye todas las obligaciones activas declaradas')}${metricPair('Gastos fijos fuera de tarjeta',cash(a.cashFixed),'Efectivo, renta, familia y suscripciones no cubiertas')}${metricPair('Gastos recurrentes futuros en tarjeta',cash(a.covered),'Se reservan como gasto futuro; nunca se suman al DTI de cuotas')}${metricPair('Necesidades mensuales registradas',cash(a.obligations),'Cuotas presentes + gasto externo + consumo recurrente futuro')}</div></div></div>${sec('Diagnóstico, límites y estrés','Los umbrales son parámetros configurables de planificación, NO límites impuestos por todos los bancos.') }<div class="grid pair"><div class="card"><h2>¿Cuánto podría asumir?</h2><div class="metricList">${metricPair('Techo de cuotas por DTI',cash(settings.dti*a.income),`${pct(settings.dti)} × ingreso reconocido`)}${metricPair('Cuotas existentes',cash(a.debt),'Se resta para hallar espacio por DTI')}${metricPair('Espacio por DTI',cash(Math.max(0,a.dtiRoom)),'Puede ser negativo antes de aplicar mínimo 0')}${metricPair('Reserva de planificación',cash(a.needed),'Mayor entre monto fijo y porcentaje del ingreso')}${metricPair('Espacio por caja recurrente',cash(Math.max(0,a.safe)),'No usa saldos de ahorro')}${metricPair('Cuota adicional propuesta',cash(a.newQuota),'Mínimo de los dos espacios; nunca garantiza aprobación')}</div></div><div class="card"><h2>Prueba de resistencia</h2><p>Ingresos formales −20%, informales ponderados −50%, moneda USD +10%, préstamos variables +2 pp anuales (aproximado).</p><div class="metricList">${metricPair('Ingreso bajo estrés',cash(a.stressIncome),'Sin alterar el score')}${metricPair('Cuotas bajo estrés',cash(a.stressDebt),'Moneda y tipos variables')}${metricPair('DTI bajo estrés',a.stressDti===null?'—':pct(a.stressDti),'Cuotas / ingreso reducido')}${metricPair('Margen bajo estrés',cash(a.stressMargin),'Después de gastos fijos declarados')}</div>${a.stressMargin<0?'<div class="callout">La prueba de estrés genera margen negativo. La capacidad adicional orientativa debería tratarse con cautela.</div>':''}</div></div>${sec('Configurar criterios de planificación','Estos ajustes cambian capacidad, nunca el score crediticio.') }<div class="card"><div class="fields three"><label>DTI objetivo (%)<input type="number" min="5" max="80" step="1" data-setting="dti" value="${Math.round(settings.dti*100)}"></label><label>Reserva mínima (RD$)<input type="number" min="0" step="100" data-setting="floor" value="${settings.floor}"></label><label>Reserva sobre ingreso (%)<input type="number" min="0" max="80" step="1" data-setting="reserve" value="${Math.round(settings.reserve*100)}"></label></div><p class="muted xs">Valores ilustrativos. Cada acreedor define sus propias políticas de originación y evaluación.</p></div>`}
function loanQuota(principal,rate,months){if(principal<=0||months<1)return 0;let r=rate/100/12;return r===0?principal/months:principal*r/(1-Math.pow(1+r,-months))}
function scenario(){let s=clone(current()),before=evaluate(s),c=s.cards.find(x=>x.id===sim.cardId);if(c){c.balance=Math.max(0,N(c.balance)-N(sim.payment));c.statementBalance=Math.max(0,N(c.statementBalance)-N(sim.payment));c.min=Math.max(0,Math.min(c.min,c.balance));if(sim.newCreditLimit>0)c.limit+=N(sim.newCreditLimit)}if(sim.loanPrincipal>0){s.loans.push({id:'simulated',name:'Préstamo hipotético',currency:'DOP',type:'personal',original:sim.loanPrincipal,balance:sim.loanPrincipal,due:loanQuota(sim.loanPrincipal,sim.loanAnnualRate,sim.loanMonths),status:'active',daysPastDue:0,variable:false});s.new0to6++}if(sim.limitRequested&&N(sim.newCreditLimit)>0)s.limitReq0to6=N(s.limitReq0to6)+1;if(sim.late30)s.late30++;s.formal=Math.max(0,s.formal+sim.formalDelta);s.informal=Math.max(0,s.informal+sim.informalDelta);s.txRate=Math.max(.01,s.txRate*(1+sim.fxShock/100));if(sim.expenseDelta) s.expenses.push({id:'sim-exp',name:'Gasto hipotético',kind:'other',amount:Math.max(0,sim.expenseDelta),onCard:false});let after=evaluate(s);return {before,after,delta:after.score-before.score,month:s}}
function field(label,key,val,options={}){const isBool=options.bool,isChoice=options.choices;const ctrl=isBool?`<select data-path="${safe(key)}"><option value="true" ${val?'selected':''}>Sí</option><option value="false" ${!val?'selected':''}>No</option></select>`:isChoice?`<select data-path="${safe(key)}">${options.choices.map(z=>`<option value="${safe(z[0])}" ${String(z[0])===String(val)?'selected':''}>${safe(z[1])}</option>`).join('')}</select>`:`<input data-path="${safe(key)}" type="${options.text?'text':'number'}" ${options.text?'':`step="${options.step||'any'}"`} value="${safe(val??'')}" ${options.placeholder?`placeholder="${safe(options.placeholder)}"`:''}>`;return `<label>${label}${ctrl}</label>`}
function subhead(title,desc){return `<div class="sectionTop" style="margin-top:19px"><div><h2>${title}</h2><p>${desc}</p></div></div>`}
